43	/// Decode the process arguments (excluding the program name) as UTF-8 text.
44	///
45	/// `env::args()` panics on arguments that are not valid UTF-8; decoding via
46	/// `args_os()` lets us report the problem as an ordinary usage error instead.
47	/// The raw bytes are never printed: the message only states *that* an
48	/// argument could not be decoded, not what it contained.
49	fn decode_args() -> Result<Vec<String>, String> {
50	    let mut out = Vec::new();
51	    for (index, arg) in env::args_os().skip(1).enumerate() {
52	        match arg.into_string() {
53	            Ok(s) => out.push(s),
54	            Err(_) => {
55	                return Err(format!(
56	                    "argument {} is not valid UTF-8 text; all arguments must be decodable text",
57	                    index + 1
58	                ));
59	            }
60	        }
61	    }
62	    Ok(out)
63	}
