586	// ---------------------------------------------------------------------------
587	// Strict JSON parser used by `verify`.
588	//
589	// Written by hand so the crate keeps zero third-party runtime dependencies.
590	// Unlike a tolerant parser it enforces every rule the verify contract relies
591	// on: exactly one complete value surrounded only by JSON whitespace, no
592	// duplicate member names within an object, strict number grammar (integers
593	// only, no fractions/exponents/leading zeros), strings decoded per RFC 8259
594	// including surrogate pairs. Anything it cannot parse is a corrupt record
595	// (exit 2), never a mismatch.
596	// ---------------------------------------------------------------------------
597	
598	mod json {
599	    #[derive(Debug, PartialEq)]
600	    pub enum JsonValue {
601	        /// Parsed as an integer because the record grammar has no fractional
602	        /// values; the width comfortably covers u32 and common JSON integers.
603	        Number(i128),
604	        String(String),
605	        Array(Vec<JsonValue>),
606	        /// Members kept in source order; names are unique (parser-enforced).
607	        Object(Vec<(String, JsonValue)>),
608	        // Accepted so documents using them parse, but records containing them
609	        // are rejected structurally by the caller.
610	        Bool(bool),
611	        Null,
612	    }
613	
614	    struct Parser<'a> {
615	        bytes: &'a [u8],
616	        pos: usize,
617	        /// Current object/array nesting depth, capped so adversarial input
618	        /// ("[[[[...")") cannot exhaust the stack and crash the verifier.
619	        depth: usize,
620	    }
621	
622	    /// Far above the depth a real record ever reaches (record → `fields`
623	    /// array → string is depth 2) while staying well within stack limits.
624	    const MAX_DEPTH: usize = 64;
625	
626	    /// Parse exactly one JSON value: optional leading/trailing JSON whitespace
627	    /// is allowed, but any trailing non-whitespace content (including a second
628	    /// object) is an error.
629	    pub fn parse_single(input: &str) -> Result<JsonValue, String> {
630	        let mut p = Parser {
631	            bytes: input.as_bytes(),
632	            pos: 0,
633	            depth: 0,
634	        };
635	        p.skip_ws();
636	        if p.pos == p.bytes.len() {
637	            return Err("input is empty; expected one JSON record".to_string());
638	        }
639	        let value = p.parse_value()?;
640	        p.skip_ws();
641	        if p.pos != p.bytes.len() {
642	            return Err(
643	                "trailing non-whitespace content after record; exactly one JSON object is allowed"
644	                    .to_string(),
645	            );
646	        }
647	        Ok(value)
648	    }
649	
650	    impl<'a> Parser<'a> {
651	        fn skip_ws(&mut self) {
652	            while self.pos < self.bytes.len()
653	                && matches!(self.bytes[self.pos], b' ' | b'\t' | b'\n' | b'\r')
654	            {
655	                self.pos += 1;
656	            }
657	        }
658	
659	        fn peek(&self) -> Option<u8> {
660	            self.bytes.get(self.pos).copied()
661	        }
662	
663	        fn enter_container(&mut self) -> Result<(), String> {
664	            if self.depth >= MAX_DEPTH {
665	                return Err("JSON nesting is too deep".to_string());
666	            }
667	            self.depth += 1;
668	            Ok(())
669	        }
670	
671	        fn parse_value(&mut self) -> Result<JsonValue, String> {
672	            self.skip_ws();
673	            match self.peek() {
674	                Some(b'{') => self.parse_object(),
675	                Some(b'[') => self.parse_array(),
676	                Some(b'"') => Ok(JsonValue::String(self.parse_string()?)),
677	                Some(b't') => self.parse_lit("true", JsonValue::Bool(true)),
678	                Some(b'f') => self.parse_lit("false", JsonValue::Bool(false)),
679	                Some(b'n') => self.parse_lit("null", JsonValue::Null),
680	                Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
681	                Some(_) => Err("unexpected character while parsing JSON".to_string()),
682	                None => Err("unexpected end of JSON input".to_string()),
683	            }
684	        }
685	
686	        fn parse_lit(&mut self, lit: &str, value: JsonValue) -> Result<JsonValue, String> {
687	            if self.bytes[self.pos..].starts_with(lit.as_bytes()) {
688	                self.pos += lit.len();
689	                Ok(value)
690	            } else {
691	                Err("malformed JSON literal".to_string())
692	            }
693	        }
694	
695	        fn parse_object(&mut self) -> Result<JsonValue, String> {
696	            self.enter_container()?;
697	            let result = self.parse_object_inner();
698	            self.depth -= 1;
699	            result
700	        }
701	
702	        fn parse_object_inner(&mut self) -> Result<JsonValue, String> {
703	            self.pos += 1; // '{'
704	            let mut entries: Vec<(String, JsonValue)> = Vec::new();
705	            self.skip_ws();
706	            if self.peek() == Some(b'}') {
707	                self.pos += 1;
708	                return Ok(JsonValue::Object(entries));
709	            }
710	            loop {
711	                self.skip_ws();
712	                if self.peek() != Some(b'"') {
713	                    return Err("expected a string member name in JSON object".to_string());
714	                }
715	                let name = self.parse_string()?;
716	                self.skip_ws();
717	                if self.peek() != Some(b':') {
718	                    return Err("expected ':' after JSON member name".to_string());
719	                }
720	                self.pos += 1;
721	                let value = self.parse_value()?;
722	                if entries.iter().any(|(n, _)| *n == name) {
723	                    return Err("JSON object contains a duplicate member".to_string());
724	                }
725	                entries.push((name, value));
726	                self.skip_ws();
727	                match self.peek() {
728	                    Some(b',') => {
729	                        self.pos += 1;
730	                    }
731	                    Some(b'}') => {
732	                        self.pos += 1;
733	                        break;
734	                    }
735	                    Some(_) => return Err("expected ',' or '}}' in JSON object".to_string()),
736	                    None => return Err("unterminated JSON object".to_string()),
737	                }
738	            }
739	            Ok(JsonValue::Object(entries))
740	        }
741	
742	        fn parse_array(&mut self) -> Result<JsonValue, String> {
743	            self.enter_container()?;
744	            let result = self.parse_array_inner();
745	            self.depth -= 1;
746	            result
747	        }
748	
749	        fn parse_array_inner(&mut self) -> Result<JsonValue, String> {
750	            self.pos += 1; // '['
751	            let mut items = Vec::new();
752	            self.skip_ws();
753	            if self.peek() == Some(b']') {
754	                self.pos += 1;
755	                return Ok(JsonValue::Array(items));
756	            }
757	            loop {
758	                items.push(self.parse_value()?);
759	                self.skip_ws();
760	                match self.peek() {
761	                    Some(b',') => {
762	                        self.pos += 1;
763	                        self.skip_ws();
764	                    }
765	                    Some(b']') => {
766	                        self.pos += 1;
767	                        break;
768	                    }
769	                    Some(_) => return Err("expected ',' or ']' in JSON array".to_string()),
770	                    None => return Err("unterminated JSON array".to_string()),
771	                }
772	            }
773	            Ok(JsonValue::Array(items))
774	        }
775	
776	        fn parse_string(&mut self) -> Result<String, String> {
777	            self.pos += 1; // opening quote
778	            let mut out = String::new();
779	            loop {
780	                match self.peek() {
781	                    None => return Err("unterminated JSON string".to_string()),
782	                    Some(b'"') => {
783	                        self.pos += 1;
784	                        break;
785	                    }
786	                    Some(b'\\') => {
787	                        self.pos += 1;
788	                        let esc = self
789	                            .peek()
790	                            .ok_or("unterminated JSON escape sequence")?;
791	                        self.pos += 1;
792	                        match esc {
793	                            b'"' => out.push('"'),
794	                            b'\\' => out.push('\\'),
795	                            b'/' => out.push('/'),
796	                            b'b' => out.push('\u{0008}'),
797	                            b'f' => out.push('\u{000c}'),
798	                            b'n' => out.push('\n'),
799	                            b'r' => out.push('\r'),
800	                            b't' => out.push('\t'),
801	                            b'u' => {
802	                                let hi = self.parse_hex4()?;
803	                                let c = if (0xD800..=0xDBFF).contains(&hi) {
804	                                    // High surrogate must be followed by "\uXXXX"
805	                                    // low surrogate; lone surrogates are invalid.
806	                                    if self.peek() != Some(b'\\') {
807	                                        return Err(
808	                                            "lone UTF-16 high surrogate in JSON string".to_string()
809	                                        );
810	                                    }
811	                                    self.pos += 1;
812	                                    if self.peek() != Some(b'u') {
813	                                        return Err(
814	                                            "bad surrogate pair escape in JSON string".to_string()
815	                                        );
816	                                    }
817	                                    self.pos += 1;
818	                                    let lo = self.parse_hex4()?;
819	                                    if !(0xDC00..=0xDFFF).contains(&lo) {
820	                                        return Err(
821	                                            "low surrogate out of range in JSON string".to_string()
822	                                        );
823	                                    }
824	                                    char::from_u32(0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00))
825	                                        .ok_or("invalid surrogate pair in JSON string")?
826	                                } else if (0xDC00..=0xDFFF).contains(&hi) {
827	                                    return Err(
828	                                        "lone UTF-16 low surrogate in JSON string".to_string()
829	                                    );
830	                                } else {
831	                                    char::from_u32(hi)
832	                                        .ok_or("invalid unicode escape in JSON string")?
833	                                };
834	                                out.push(c);
835	                            }
836	                            _ => {
837	                                return Err("invalid escape sequence in JSON string".to_string())
838	                            }
839	                        }
840	                    }
841	                    Some(c) if c < 0x20 => {
842	                        return Err("unescaped control character in JSON string".to_string())
843	                    }
844	                    Some(_) => {
845	                        // Copy one whole UTF-8 scalar at a time, validating that
846	                        // the raw bytes really are UTF-8 (the surrounding input
847	                        // is &str so this cannot fail, but keep the boundary
848	                        // explicit rather than slicing mid-char).
849	                        let start = self.pos;
850	                        self.pos += 1;
851	                        while self.pos < self.bytes.len() {
852	                            let b = self.bytes[self.pos];
853	                            if b == b'"' || b == b'\\' || b < 0x20 {
854	                                break;
855	                            }
856	                            self.pos += 1;
857	                        }
858	                        let chunk = std::str::from_utf8(&self.bytes[start..self.pos])
859	                            .map_err(|_| "invalid UTF-8 inside JSON string".to_string())?;
860	                        out.push_str(chunk);
861	                    }
862	                }
863	            }
864	            Ok(out)
865	        }
866	
867	        fn parse_hex4(&mut self) -> Result<u32, String> {
868	            let mut v = 0u32;
869	            for _ in 0..4 {
870	                if self.peek().is_none() {
871	                    return Err("truncated \\u escape in JSON string".to_string());
872	                }
873	                let c = self.peek().unwrap();
874	                if !(c as char).is_ascii_hexdigit() {
875	                    return Err("bad hexadecimal digit in \\u escape".to_string());
876	                }
877	                let d = (c as char).to_digit(16).unwrap();
878	                self.pos += 1;
879	                v = v * 16 + d;
880	            }
881	            Ok(v)
882	        }
883	
884	        /// Strict RFC 8259 integer grammar. The record format has no fractional
885	        /// values, so `.`/`e` forms are rejected rather than truncated.
886	        fn parse_number(&mut self) -> Result<JsonValue, String> {
887	            let start = self.pos;
888	            if self.peek() == Some(b'-') {
889	                self.pos += 1;
890	            }
891	            match self.peek() {
892	                Some(b'0') => {
893	                    self.pos += 1;
894	                    // A leading zero must not be followed by more digits.
895	                    if matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
896	                        return Err("numbers with leading zeros are not valid JSON".to_string());
897	                    }
898	                }
899	                Some(c) if c.is_ascii_digit() => {
900	                    while matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
901	                        self.pos += 1;
902	                    }
903	                }
904	                _ => return Err("malformed JSON number".to_string()),
905	            }
906	            // No fraction or exponent: this grammar only carries integers.
907	            if matches!(self.peek(), Some(b'.' | b'e' | b'E')) {
908	                return Err(
909	                    "record numbers must be integers; fractions and exponents are not accepted"
910	                        .to_string(),
911	                );
912	            }
913	            let text = std::str::from_utf8(&self.bytes[start..self.pos])
914	                .map_err(|_| "invalid UTF-8 in JSON number".to_string())?;
915	            text.parse::<i128>()
916	                .map(JsonValue::Number)
917	                .map_err(|_| "JSON integer is out of supported range".to_string())
918	        }
919	    }
920	}
