383	#[test]
384	fn verify_key_version_range_endpoints_are_normal_versions() {
385	    // Both endpoints of 1..=4294967295 are ordinary usable versions: with the
386	    // correct key the record verifies (exit 0, exactly one {"valid":true}
387	    // line, empty stderr). The key version is independent of the record's
388	    // format version: a key version other than 1 must never be reported as an
389	    // unsupported format.
390	    for (token, golden) in [("1", KV_TAG_V1), ("4294967295", KV_TAG_VMAX)] {
391	        let rec = kv_record(token, golden);
392	
393	        let out = run_verify(KV_KEY, rec.as_bytes());
394	        assert_eq!(out.status.code(), Some(0), "version {token}: stderr={:?}", String::from_utf8_lossy(&out.stderr));
395	        assert_eq!(out.stdout, b"{\"valid\":true}\n");
396	        assert!(out.stderr.is_empty(), "version {token}: stderr must be empty");
397	
398	        // The same structurally legal record under a wrong key is a mismatch,
399	        // not a format/structure rejection.
400	        let out = run_verify(KV_WRONG_KEY, rec.as_bytes());
401	        assert_eq!(out.status.code(), Some(1), "version {token}: wrong key must mismatch");
402	        assert_eq!(out.stdout, b"{\"valid\":false}\n");
403	        assert!(out.stderr.is_empty());
404	    }
405	}
