407	#[test]
408	fn verify_changing_an_in_range_key_version_is_a_mismatch_not_corruption() {
409	    // Everything else (including the original tag) stays fixed; only the
410	    // version moves to another in-range integer. The record stays legal but
411	    // the authenticated content changed, so the result is exit 1 with BOTH the
412	    // correct key and a wrong key: a wrong key must not reclassify the legal
413	    // version number as corrupt input.
414	    let variants = [
415	        kv_record("2", KV_TAG_V1),                 // 1 -> 2
416	        kv_record("4294967295", KV_TAG_V1),        // 1 -> high endpoint
417	        kv_record("1", KV_TAG_VMAX),               // max -> 1 with max's tag
418	        // Legal JSON whitespace around members and around the number must not
419	        // change the version's meaning: still a structural legal mismatch.
420	        format!(
421	            r#"{{ "format" : 1 , "algorithm" : "HMAC-SHA256" , "key_id" : "{KV_KID}" , "key_version" : 2 , "fields" : [ "{KV_FIELD}" ] , "tag" : "{KV_TAG_V1}" }}"#
422	        ),
423	    ];
424	    for rec in variants {
425	        for key in [KV_KEY, KV_WRONG_KEY] {
426	            let out = run_verify(key, rec.as_bytes());
427	            assert_eq!(
428	                out.status.code(),
429	                Some(1),
430	                "expected mismatch for {rec}, stderr={:?}",
431	                String::from_utf8_lossy(&out.stderr)
432	            );
433	            assert_eq!(out.stdout, b"{\"valid\":false}\n");
434	            assert!(out.stderr.is_empty(), "mismatch must be silent on stderr");
435	        }
436	    }
437	}
