595	// ---------------------------------------------------------------------------
596	// Minimal JSON parser (objects, arrays, strings, integers, true/false/null).
597	// ---------------------------------------------------------------------------
598	
599	#[derive(Debug, Clone)]
600	enum Json {
601	    Null,
602	    // Retained for parser completeness; records carry no boolean values.
603	    #[allow(dead_code)]
604	    Bool(bool),
605	    Num(i64),
606	    Str(String),
607	    Arr(Vec<Json>),
608	    Obj(Vec<(String, Json)>),
609	}
610	
611	impl Json {
612	    fn parse(s: &str) -> Json {
613	        let mut p = Parser {
614	            chars: s.chars().collect(),
615	            pos: 0,
616	        };
617	        p.ws();
618	        let v = p.value();
619	        p.ws();
620	        assert_eq!(p.pos, p.chars.len(), "trailing data after JSON record: {s}");
621	        v
622	    }
623	
624	    fn as_str(&self) -> &str {
625	        match self {
626	            Json::Str(s) => s,
627	            other => panic!("expected JSON string, got {other:?}"),
628	        }
629	    }
630	
631	    fn as_i64(&self) -> i64 {
632	        match self {
633	            Json::Num(n) => *n,
634	            other => panic!("expected JSON number, got {other:?}"),
635	        }
636	    }
637	
638	    fn as_array(&self) -> &[Json] {
639	        match self {
640	            Json::Arr(a) => a,
641	            other => panic!("expected JSON array, got {other:?}"),
642	        }
643	    }
644	
645	    fn as_object(&self) -> &[(String, Json)] {
646	        match self {
647	            Json::Obj(o) => o,
648	            other => panic!("expected JSON object, got {other:?}"),
649	        }
650	    }
651	
652	    fn get(&self, key: &str) -> &Json {
653	        let obj = self.as_object();
654	        let idx = obj
655	            .iter()
656	            .position(|(k, _)| k == key)
657	            .unwrap_or_else(|| panic!("missing key {key:?} in {self:?}"));
658	        &obj[idx].1
659	    }
660	
661	    /// Every string value anywhere in the document.
662	    fn strings(&self, out: &mut Vec<String>) {
663	        match self {
664	            Json::Str(s) => out.push(s.clone()),
665	            Json::Arr(a) => a.iter().for_each(|v| v.strings(out)),
666	            Json::Obj(o) => o.iter().for_each(|(_, v)| v.strings(out)),
667	            Json::Null | Json::Bool(_) | Json::Num(_) => {}
668	        }
669	    }
670	}
671	
672	struct Parser {
673	    chars: Vec<char>,
674	    pos: usize,
675	}
676	
677	impl Parser {
678	    fn ws(&mut self) {
679	        while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
680	            self.pos += 1;
681	        }
682	    }
683	
684	    fn bump(&mut self) -> char {
685	        assert!(self.pos < self.chars.len(), "unexpected end of JSON");
686	        let c = self.chars[self.pos];
687	        self.pos += 1;
688	        c
689	    }
690	
691	    fn expect(&mut self, want: char) {
692	        assert!(self.pos < self.chars.len(), "expected {want:?}, found end of JSON");
693	        let got = self.chars[self.pos];
694	        assert_eq!(got, want, "expected {want:?} at position {}", self.pos);
695	        self.pos += 1;
696	    }
697	
698	    fn value(&mut self) -> Json {
699	        self.ws();
700	        assert!(self.pos < self.chars.len(), "unexpected end of JSON");
701	        match self.chars[self.pos] {
702	            '{' => self.object(),
703	            '[' => self.array(),
704	            '"' => Json::Str(self.string()),
705	            't' | 'f' => self.boolean(),
706	            'n' => self.null(),
707	            c if c == '-' || c.is_ascii_digit() => self.number(),
708	            c => panic!("unexpected character {c:?} in JSON"),
709	        }
710	    }
711	
712	    fn object(&mut self) -> Json {
713	        self.expect('{');
714	        let mut entries = Vec::new();
715	        self.ws();
716	        if self.chars[self.pos] == '}' {
717	            self.pos += 1;
718	            return Json::Obj(entries);
719	        }
720	        loop {
721	            self.ws();
722	            let key = self.string();
723	            self.ws();
724	            self.expect(':');
725	            let val = self.value();
726	            entries.push((key, val));
727	            self.ws();
728	            match self.bump() {
729	                ',' => continue,
730	                '}' => break,
731	                c => panic!("bad object separator {c:?}"),
732	            }
733	        }
734	        Json::Obj(entries)
735	    }
736	
737	    fn array(&mut self) -> Json {
738	        self.expect('[');
739	        let mut items = Vec::new();
740	        self.ws();
741	        if self.chars[self.pos] == ']' {
742	            self.pos += 1;
743	            return Json::Arr(items);
744	        }
745	        loop {
746	            items.push(self.value());
747	            self.ws();
748	            match self.bump() {
749	                ',' => continue,
750	                ']' => break,
751	                c => panic!("bad array separator {c:?}"),
752	            }
753	        }
754	        Json::Arr(items)
755	    }
756	
757	    fn string(&mut self) -> String {
758	        self.expect('"');
759	        let mut out = String::new();
760	        loop {
761	            match self.bump() {
762	                '"' => break,
763	                '\\' => match self.bump() {
764	                    '"' => out.push('"'),
765	                    '\\' => out.push('\\'),
766	                    '/' => out.push('/'),
767	                    'b' => out.push('\u{0008}'),
768	                    'f' => out.push('\u{000c}'),
769	                    'n' => out.push('\n'),
770	                    'r' => out.push('\r'),
771	                    't' => out.push('\t'),
772	                    'u' => {
773	                        let hi = self.hex4();
774	                        let c = if (0xD800..=0xDBFF).contains(&hi) {
775	                            assert_eq!(self.bump(), '\\');
776	                            assert_eq!(self.bump(), 'u');
777	                            let lo = self.hex4();
778	                            assert!(
779	                                (0xDC00..=0xDFFF).contains(&lo),
780	                                "bad low surrogate {lo:x}"
781	                            );
782	                            char::from_u32(0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00))
783	                                .expect("bad surrogate pair")
784	                        } else {
785	                            char::from_u32(hi).expect("bad unicode escape")
786	                        };
787	                        out.push(c);
788	                    }
789	                    c => panic!("bad escape \\{c}"),
790	                },
791	                // Raw control bytes must not appear unescaped in JSON text.
792	                c if (c as u32) < 0x20 => panic!("unescaped control character {c:?} in JSON"),
793	                c => out.push(c),
794	            }
795	        }
796	        out
797	    }
798	
799	    fn hex4(&mut self) -> u32 {
800	        let mut v = 0u32;
801	        for _ in 0..4 {
802	            let c = self.bump();
803	            v = v * 16 + c.to_digit(16).unwrap_or_else(|| panic!("bad hex digit {c:?}"));
804	        }
805	        v
806	    }
807	
808	    fn number(&mut self) -> Json {
809	        let start = self.pos;
810	        if self.chars[self.pos] == '-' {
811	            self.pos += 1;
812	        }
813	        while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
814	            self.pos += 1;
815	        }
816	        let text: String = self.chars[start..self.pos].iter().collect();
817	        Json::Num(text.parse().unwrap_or_else(|_| panic!("bad number {text}")))
818	    }
819	
820	    fn boolean(&mut self) -> Json {
821	        if self.chars[self.pos] == 't' {
822	            for want in "true".chars() {
823	                self.expect(want);
824	            }
825	            Json::Bool(true)
826	        } else {
827	            for want in "false".chars() {
828	                self.expect(want);
829	            }
830	            Json::Bool(false)
831	        }
832	    }
833	
834	    fn null(&mut self) -> Json {
835	        for want in "null".chars() {
836	            self.expect(want);
837	        }
838	        Json::Null
839	    }
840	}
